using System.ComponentModel.DataAnnotations;
namespace Project_QLThoiTrang.Models;
public class ChatThread { public int CustomerId{get;set;} public DateTime UpdatedUtc{get;set;} public long CustomerReadId{get;set;} public long StaffReadId{get;set;} }
public class ChatMessage { public long Id{get;set;} public int CustomerId{get;set;} public int SenderId{get;set;} public string Text{get;set;}=""; public Guid ClientToken{get;set;} public DateTime CreatedUtc{get;set;} }
public class ResetCode { public Guid Id{get;set;} public int CustomerId{get;set;} public string Hash{get;set;}=""; public string Stamp{get;set;}=""; public DateTime CreatedUtc{get;set;} public DateTime ExpiresUtc{get;set;} public int Attempts{get;set;} public bool Sent{get;set;} public DateTime? UsedUtc{get;set;} }
public class InventoryValue { public int VariantId{get;set;} public decimal? AverageCost{get;set;} public int? ActorId{get;set;} public DateTime UpdatedUtc{get;set;} public string Note{get;set;}=""; }
public class SupplierAccount { public int ReceiptId{get;set;} public decimal Amount{get;set;} public string Note{get;set;}=""; public int ActorId{get;set;} public DateTime UpdatedUtc{get;set;} }
public class SupplierPayment { public long Id{get;set;} public int ReceiptId{get;set;} public decimal Amount{get;set;} public string Reference{get;set;}=""; public int ActorId{get;set;} public DateTime CreatedUtc{get;set;} }
public class Shipment { public int OrderId{get;set;} public string ClientCode{get;set;}=""; public string RequestHash{get;set;}=""; public string? TrackingCode{get;set;} public string Status{get;set;}="Pending"; public DateTime UpdatedUtc{get;set;} public string Error{get;set;}=""; }
public class ForgotInput { [Required,EmailAddress,StringLength(150)] public string Email{get;set;}=""; }
public class ResetInput { [Required,EmailAddress] public string Email{get;set;}=""; [Required,RegularExpression(@"^\d{6}$")] public string Code{get;set;}=""; [Required,MinLength(8),StringLength(100),RegularExpression(@"^(?=.*\p{L})(?=.*\d).+$")] public string Password{get;set;}=""; [Compare(nameof(Password))] public string ConfirmPassword{get;set;}=""; }
public class ShipmentInput { public string Id{get;set;}=""; [Required,StringLength(100)] public string Province{get;set;}=""; [Required,StringLength(100)] public string Ward{get;set;}=""; [Range(1,19999)] public int Weight{get;set;}=500; [Range(1,200)] public int Length{get;set;}=20; [Range(1,200)] public int Width{get;set;}=15; [Range(1,200)] public int Height{get;set;}=10; }
public class BankTransferOptions { public bool Enabled{get;set;} public string QrImage{get;set;}="/images/payments/transfer-qr.png"; }
public class SmtpOptions { public string Host{get;set;}=""; public int Port{get;set;}=587; public string User{get;set;}=""; public string Password{get;set;}=""; public string From{get;set;}=""; public bool EnableSsl{get;set;}=true; public bool Ready=>!string.IsNullOrWhiteSpace(Host)&&!string.IsNullOrWhiteSpace(From); }
public class GhnOptions { public bool Enabled{get;set;} public string Token{get;set;}=""; public int ShopId{get;set;} public string BaseUrl{get;set;}="https://dev-online-gateway.ghn.vn/shiip/public-api/"; public bool Ready=>Enabled&&Token.Length>0&&ShopId>0; }
public record ProfitLine(string OrderId,DateTime Date,string Product,int Quantity,decimal Revenue,decimal? Cost){public decimal? Profit=>Cost.HasValue?Revenue-Cost:null;}
